 else$update($table,$column,$id,match($name){'manual_reference'=>['reference'=>'CHANGED BETWEEN REQUESTS'],'batch_content_hash'=>['content_hash'=>str_repeat('0',64)],'core_provider_actor','core_components_actor','core_journal_actor'=>['actor_id'=>15],'core_provider_metadata','core_components_metadata','core_journal_metadata'=>['metadata_json'=>'{"mutated_after_commit":true}'],default=>['created_at'=>'2001-01-01 00:00:00']});
 $mutated=$lateSnapshot();essentialCheck($mutated!==$clean,'Late '.$name.' actually changes persisted source bytes');$error=null;try{$apply($event,$proof);}catch(Throwable$e){$error=$e->getMessage();}
