 if($name==='manual_deleted'||($coreKind!==null&&str_ends_with($name,'_deleted')))IssuerStorage::query($db,'INSERT INTO '.$p.$table.' (`'.implode('`,`',array_keys($old)).'`) VALUES('.implode(',',array_fill(0,count($old),'?')).')',array_values($old));else$update($table,$column,$id,$old);
 essentialCheck($lateSnapshot()===$clean,'Restoring only the injected source fault restores the original complete byte snapshot');essentialCheck($apply($event,$proof)===$payment&&$lateSnapshot()===$clean,'Same proof retries to the original payment after only source restoration');$results[$name]=['rejected'=>$error,'no_new_effects'=>true,'restored_same_payment'=>$payment];
}
